using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;

namespace CodexQuotaMonitor {
 public static class Tests {
  public const string Fixture="{\"rateLimits\":{\"planType\":\"pro\",\"primary\":{\"usedPercent\":100,\"windowDurationMins\":10080,\"resetsAt\":1791948554},\"credits\":{\"balance\":\"56104.7369115000\"}},\"rateLimitResetCredits\":{\"availableCount\":1,\"credits\":[{\"status\":\"available\",\"expiresAt\":1794008446}]}}";
  static Snapshot Data(string value){return Snapshot.Parse(Json.Parse(value),null);}
  public static int Run(string path) {
   var results=new List<string>();int errors=0;
   Action<string,Action> test=(name,action)=>{try{action();results.Add(name+":passed");}catch{errors++;results.Add(name+":failed");}};
   test("weekly-used-is-not-remaining",()=>{var s=Data(Fixture);Require(s.Windows.Count==1&&s.Windows[0].Remaining==0&&s.Windows[0].Label=="周额度"&&s.Title=="ChatGPT Pro");});
   test("credit-precision-and-reset-details",()=>{var s=Data(Fixture);Require(s.Credits=="56,104.74"&&s.Resets==1&&s.ResetExpirations[0]==1794008446);});
   test("missing-fields-remain-unknown",()=>{var s=Data("{\"rateLimits\":{\"primary\":{}}}");Require(s.Windows.Count==1&&s.Windows[0].Remaining==null&&s.Credits==null&&s.Resets==null&&s.Windows[0].ResetsAt==null);});
   test("absent-window-not-zero",()=>Require(Data("{}").Windows.Count==0));
   test("multiple-buckets-keep-independent-windows",()=>{var s=Data("{\"rateLimits\":{\"primary\":{\"usedPercent\":99}},\"rateLimitsByLimitId\":{\"special\":{\"primary\":{\"usedPercent\":10,\"windowDurationMins\":300}},\"codex\":{\"primary\":{\"usedPercent\":20,\"windowDurationMins\":10080},\"secondary\":{\"usedPercent\":30,\"windowDurationMins\":300}}}}");Require(s.Windows.Count==3&&s.Windows[0].Bucket=="codex"&&s.Windows[0].Remaining==80&&s.Windows[1].Remaining==70&&s.Windows[2].Remaining==90);});
   test("percent-clamped",()=>{Require(Data("{\"rateLimits\":{\"primary\":{\"usedPercent\":105},\"secondary\":{\"usedPercent\":-5}}}").Windows.Select(w=>w.Remaining).SequenceEqual(new double?[]{0,100}));});
   test("reset-count-authoritative",()=>{Require(Data("{\"rateLimitResetCredits\":{\"availableCount\":3,\"credits\":null}}").Resets==3);});
   test("unlimited-credit-label",()=>Require(Data("{\"rateLimits\":{\"credits\":{\"unlimited\":true}}}").Credits=="不限额"));
   test("no-repeat-or-three-alerts-at-exhaustion",()=>{var a=new AlertState();var s=Data(Fixture);Require(a.Update(null,s,"a",20,10).Count==1);Require(a.Update(s,s,"a",20,10).Count==0);});
   test("warning-critical-crossings",()=>{var a=new AlertState();var s=Data(Fixture);s.Windows[0].Remaining=21;Require(a.Update(null,s,"a",20,10).Count==0);s.Windows[0].Remaining=20;Require(a.Update(null,s,"a",20,10).Count==1);s.Windows[0].Remaining=15;Require(a.Update(null,s,"a",20,10).Count==0);s.Windows[0].Remaining=10;Require(a.Update(null,s,"a",20,10).Count==1);s.Windows[0].Remaining=0;Require(a.Update(null,s,"a",20,10).Count==1);});
   test("new-window-and-account-reset-dedup",()=>{var a=new AlertState();var s=Data(Fixture);a.Update(null,s,"a",20,10);Require(a.Update(null,s,"b",20,10).Count==1);s.Windows[0].ResetsAt+=3600;Require(a.Update(null,s,"a",20,10).Count==1);});
   test("reset-time-jitter-does-not-repeat",()=>{var a=new AlertState();var s=Data(Fixture);a.Update(null,s,"a",20,10);s.Windows[0].ResetsAt+=1;Require(a.Update(null,s,"a",20,10).Count==0);s.Windows[0].ResetsAt-=2;Require(a.Update(null,s,"a",20,10).Count==0);var restored=new AlertState{Seen=new HashSet<string>(a.Seen),ResetAnchors=new Dictionary<string,long>(a.ResetAnchors)};Require(restored.Update(null,s,"a",20,10).Count==0);});
   test("restored-notified-once",()=>{var a=new AlertState();var old=Data(Fixture);var fresh=Data(Fixture);fresh.Windows[0].Remaining=100;Require(a.Update(old,fresh,"a",20,10).Count==1);Require(a.Update(old,fresh,"a",20,10).Count==0);});
   test("unknown-no-threshold-alert",()=>Require(new AlertState().Update(null,Data("{\"rateLimits\":{\"primary\":{}}}"),"a",20,10).Count==0));
   test("plan-is-from-account",()=>Require(Snapshot.Parse(Json.Parse(Fixture),"plus").Title=="ChatGPT Plus"));
   test("readonly-rpc-whitelist",()=>{using(var c=new CodexClient()){bool rejected=false;try{c.CallAsync("account/rateLimitResetCredit/consume").GetAwaiter().GetResult();}catch(InvalidOperationException){rejected=true;}Require(rejected);}});
   test("old-settings-preserve-options-and-default-smaller-corner",()=>{var settings=Json.Serializer.Deserialize<Settings>("{\"Interval\":15,\"Topmost\":true,\"Theme\":\"dark\",\"Alerts\":[\"existing\"],\"Left\":500,\"Top\":30}");Require(settings.Interval==15&&settings.Topmost&&settings.Theme=="dark"&&settings.Alerts[0]=="existing"&&settings.Scale==0.75&&settings.DockBottomRight);var restored=Json.Serializer.Deserialize<Settings>(Json.Encode(settings));Require(restored.Scale==0.75&&restored.DockBottomRight&&restored.Left==500);});
   test("taskbar-prefers-right-free-slot-and-preserves-icons",()=>{var bar=new System.Drawing.Rectangle(0,1392,2560,48);var occupied=new[]{new System.Drawing.Rectangle(2,1400,276,32),new System.Drawing.Rectangle(708,1392,1145,48),new System.Drawing.Rectangle(2143,1392,417,48)};var rect=TaskbarHost.FindSpace(bar,occupied,250,36,8);Require(rect==new System.Drawing.Rectangle(1885,1398,250,36)&&occupied.All(r=>!r.IntersectsWith(rect)));});
   test("taskbar-no-room-hides-rather-than-covering-controls",()=>Require(TaskbarHost.FindSpace(new System.Drawing.Rectangle(0,0,300,48),new[]{new System.Drawing.Rectangle(0,0,300,48)},250,36,8).IsEmpty));
   test("taskbar-left-edge-and-coexists-with-traffic-monitor",()=>{var bar=new System.Drawing.Rectangle(0,1392,2560,48);var buttons=new System.Drawing.Rectangle(730,1392,1100,48);Require(TaskbarHost.FindSpace(bar,new[]{buttons},250,36,8,true).Left==8);Require(TaskbarHost.FindSpace(bar,new[]{buttons,new System.Drawing.Rectangle(2,1400,276,32)},250,36,8,true).Left==286);});
   test("taskbar-overlapping-occupied-ranges-and-negative-screen",()=>{var bar=new System.Drawing.Rectangle(-1920,-48,1920,48);var occupied=new[]{new System.Drawing.Rectangle(-1900,-48,500,48),new System.Drawing.Rectangle(-1700,-48,500,48),new System.Drawing.Rectangle(-300,-48,300,48)};var rect=TaskbarHost.FindSpace(bar,occupied,250,36,8);Require(!rect.IsEmpty&&bar.Contains(rect)&&occupied.All(r=>!r.IntersectsWith(rect)));});
   test("old-settings-taskbar-opt-in-and-roundtrip",()=>{var settings=Json.Serializer.Deserialize<Settings>("{\"Interval\":5}");Require(!settings.TaskbarMode);settings.TaskbarMode=true;Require(Json.Serializer.Deserialize<Settings>(Json.Encode(settings)).TaskbarMode);});
   test("taskbar-expiry-from-reset-credit-not-quota-reset",()=>{var s=Data(Fixture);var view=TaskbarContent.Create(s,false);var date=DateTimeOffset.FromUnixTimeSeconds(s.ResetExpirations[0].Value).ToLocalTime();Require(view.ResetExpiry.Contains(date.ToString("MM/dd HH:mm"))&&!view.ResetExpiry.Contains(DateTimeOffset.FromUnixTimeSeconds(s.Windows[0].ResetsAt.Value).ToLocalTime().ToString("MM/dd HH:mm")));});
   test("taskbar-earliest-expiry-and-all-expirations-in-tooltip",()=>{var s=Data(Fixture);var first=s.ResetExpirations[0].Value;s.Resets=3;s.ResetExpirations=new List<long?>{first+86400,null,first};var view=TaskbarContent.Create(s,false);Require(view.ResetExpiry==TaskbarContent.Expiry(Data(Fixture))&&view.Tooltip.Contains(Snapshot.Time(first+86400))&&view.Tooltip.Contains(Snapshot.Time(first))&&view.Tooltip.Contains("部分重置"));});
   test("taskbar-no-reset-and-missing-expiry-remain-distinct",()=>{var s=Data(Fixture);s.Resets=0;Require(TaskbarContent.Create(s,false).ResetExpiry=="暂无可用重置");s.Resets=1;s.ResetExpirations.Clear();var view=TaskbarContent.Create(s,false);Require(view.ResetExpiry=="到期暂不可用"&&view.Tooltip.Contains("额度恢复"));});
   test("taskbar-stale-credits-reset-and-null-clear-old-expiry",()=>{var s=Data(Fixture);var stale=TaskbarContent.Create(s,true);Require(stale.Plan.StartsWith("更新失败")&&stale.CreditsLabel.Contains("旧")&&stale.ResetLabel.Contains("旧")&&stale.Tooltip.Contains("上次成功"));Require(TaskbarContent.Create(null,false).ResetExpiry=="到期暂不可用");});
   test("taskbar-wider-layout-still-fits-beside-traffic-monitor",()=>{var bar=new System.Drawing.Rectangle(0,1392,2560,48);var occupied=new[]{new System.Drawing.Rectangle(2,1400,276,32),new System.Drawing.Rectangle(730,1392,1100,48)};var rect=TaskbarHost.FindSpace(bar,occupied,390,40,8,true);Require(rect.Left==286&&rect.Width==390&&rect.Height==40&&occupied.All(r=>!r.IntersectsWith(rect)));});
   test("token-int64-authoritative-no-local-sum",()=>{var u=TokenUsage.Parse(Json.Parse("{\"summary\":{\"lifetimeTokens\":42784428789},\"dailyUsageBuckets\":[{\"startDate\":\"2026-10-10\",\"tokens\":159650195}]}"));Require(u.LifetimeTokens==42784428789L&&u.ForDate("2026-10-10")==159650195L&&TokenUsage.Full(u.LifetimeTokens)=="42,784,428,789"&&TokenUsage.Compact(u.LifetimeTokens)=="≈427.84亿");});
   test("token-missing-day-is-not-zero-and-midnight-rollover",()=>{var u=TokenUsage.Parse(Json.Parse("{\"summary\":{},\"dailyUsageBuckets\":[{\"startDate\":\"2026-10-10\",\"tokens\":0}]}"));Require(u.LifetimeTokens==null&&u.ForDate("2026-10-10")==0&&u.ForDate("2026-10-11")==null&&u.Detail(false,"2026-10-11").Contains("暂未返回该日数据"));});
   test("token-null-empty-invalid-and-duplicate-buckets",()=>{foreach(var root in new[]{"{\"summary\":{\"lifetimeTokens\":null},\"dailyUsageBuckets\":null}","{\"summary\":{\"lifetimeTokens\":-1},\"dailyUsageBuckets\":[]}","{\"summary\":{\"lifetimeTokens\":1.5},\"dailyUsageBuckets\":[{\"startDate\":\"bad\",\"tokens\":5},{\"startDate\":\"2026-02-30\",\"tokens\":5}]}"}){var u=TokenUsage.Parse(Json.Parse(root));Require(u.LifetimeTokens==null&&u.Daily.Count==0);}
    var duplicate=TokenUsage.Parse(Json.Parse("{\"summary\":{},\"dailyUsageBuckets\":[{\"startDate\":\"2026-10-10\",\"tokens\":5},{\"startDate\":\"2026-10-10\",\"tokens\":5}]}"));Require(duplicate.ForDate("2026-10-10")==5);});
   test("token-refresh-failure-preserves-only-last-valid-usage",()=>{var s=Data(Fixture);s.Usage=TokenUsage.Parse(Json.Parse("{\"summary\":{\"lifetimeTokens\":50}}"));var previous=s.Usage;
    TokenUsage.RefreshAsync(s,()=>System.Threading.Tasks.Task.FromResult<object>(Json.Parse("{}"))).GetAwaiter().GetResult();Require(s.Usage==previous&&s.UsageStale&&s.Windows[0].Remaining==0);
    TokenUsage.RefreshAsync(s,()=>{throw new InvalidOperationException("RPC_-32601");}).GetAwaiter().GetResult();Require(s.Usage==previous&&s.UsageStale);
    TokenUsage.RefreshAsync(s,()=>System.Threading.Tasks.Task.FromResult<object>(Json.Parse("{\"summary\":{\"lifetimeTokens\":60}}"))).GetAwaiter().GetResult();Require(s.Usage.LifetimeTokens==60&&!s.UsageStale);});
   test("token-conflicting-buckets-reject-new-response",()=>{var s=Data(Fixture);TokenUsage.RefreshAsync(s,()=>System.Threading.Tasks.Task.FromResult<object>(Json.Parse("{\"summary\":{},\"dailyUsageBuckets\":[{\"startDate\":\"2026-10-10\",\"tokens\":5},{\"startDate\":\"2026-10-10\",\"tokens\":6}]}"))).GetAwaiter().GetResult();Require(s.Usage==null&&s.UsageStale);});
   test("token-taskbar-stale-clear-and-independent-quota",()=>{var s=Data(Fixture);s.Usage=TokenUsage.Parse(Json.Parse("{\"summary\":{\"lifetimeTokens\":5000000000}}"));var view=TaskbarContent.Create(s,false);Require(view.TotalTokens=="累计 50亿"&&view.YesterdayTokens.Contains("暂未更新"));s.UsageStale=true;view=TaskbarContent.Create(s,false);Require(view.Plan=="ChatGPT Pro"&&view.TotalTokens=="旧累计 50亿"&&view.TokensStale&&view.Tooltip.Contains("Token 更新失败"));var empty=TaskbarContent.Create(null,false);Require(empty.TotalTokens=="累计 —"&&!empty.Tooltip.Contains("50亿"));});
   test("token-display-Chinese-units-rounding-and-boundaries",()=>{Require(TokenUsage.Compact(null)=="—"&&TokenUsage.Compact(0)=="0"&&TokenUsage.Compact(9999)=="9999"&&TokenUsage.Compact(10000)=="1万"&&TokenUsage.Compact(10001)=="≈1万"&&TokenUsage.Compact(12345)=="≈1.23万"&&TokenUsage.Compact(99999999)=="≈1亿"&&TokenUsage.Compact(100000000)=="1亿"&&TokenUsage.Compact(1000000000000)=="1万亿"&&TokenUsage.Compact(159650195)=="≈1.6亿"&&TokenUsage.Compact(long.MaxValue)=="≈9223372.04万亿");});
   test("token-four-column-layout-avoids-occupied-slot",()=>{var bar=new System.Drawing.Rectangle(0,1392,2560,48);var controls=new[]{new System.Drawing.Rectangle(730,1392,1100,48)};Require(TaskbarHost.FindSpace(bar,controls,480,40,8,true)==new System.Drawing.Rectangle(8,1396,480,40));var withTraffic=controls.Concat(new[]{new System.Drawing.Rectangle(2,1400,276,32)});var rect=TaskbarHost.FindSpace(bar,withTraffic,480,40,8,true);Require(!rect.IsEmpty&&withTraffic.All(r=>!r.IntersectsWith(rect)));});
   test("token-yesterday-China-midnight-leap-and-year-boundaries",()=>{Require(TokenUsage.PreviousDate(DateTimeOffset.Parse("2026-10-10T15:59:59Z"))=="2026-10-09"&&TokenUsage.PreviousDate(DateTimeOffset.Parse("2026-10-10T16:00:00Z"))=="2026-10-10"&&TokenUsage.PreviousDate(DateTimeOffset.Parse("2024-02-29T16:00:00Z"))=="2024-02-29"&&TokenUsage.PreviousDate(DateTimeOffset.Parse("2025-12-31T16:00:00Z"))=="2025-12-31");});
   test("token-yesterday-selection-not-latest-bucket-or-zero-fallback",()=>{var u=TokenUsage.Parse(Json.Parse("{\"summary\":{},\"dailyUsageBuckets\":[{\"startDate\":\"2026-10-09\",\"tokens\":7},{\"startDate\":\"2026-10-10\",\"tokens\":0},{\"startDate\":\"2026-10-11\",\"tokens\":99}]}"));var date=TokenUsage.PreviousDate(DateTimeOffset.Parse("2026-10-11T04:00:00Z"));Require(u.ForDate(date)==0&&u.Detail(false,date).Contains("昨日（2026-10-10）：0 token"));u.Daily.Remove(date);Require(u.ForDate(date)==null&&u.Detail(false,date).Contains("暂未返回该日数据"));});
   test("system-cpu-kernel-includes-idle-and-reset-is-unknown",()=>{Require(Math.Abs(SystemUsage.CpuPercent(70,100,20,0,0,0).Value-41.6666667)<0.001);Require(SystemUsage.CpuPercent(0,0,0,0,0,0)==null&&SystemUsage.CpuPercent(1,2,1,3,4,3)==null&&SystemUsage.CpuPercent(20,10,1,0,0,0)==null);});
   test("network-rates-counter-reset-and-zero",()=>{Require(SystemUsage.Rate(2048,1024,2)==512&&SystemUsage.Rate(1,2,1)==null&&SystemUsage.Rate(1,0,0)==null&&SystemUsage.Rate(100,100,1)==0);});
   test("system-speed-units-and-unknown",()=>{Require(SystemUsage.Speed(null)=="—"&&SystemUsage.Speed(-1)=="—"&&SystemUsage.Speed(0)=="0.00 KB/s"&&SystemUsage.Speed(1024)=="1.00 KB/s"&&SystemUsage.Speed(1024*1024)=="1.00 MB/s"&&SystemUsage.Percent(null)=="—"&&SystemUsage.Percent(0)=="0 %");});
   test("gpu-group-processes-by-engine-and-take-busiest",()=>{var values=new[]{new KeyValuePair<string,double>("pid_1_luid_0x0_0x1_phys_0_eng_0_engtype_3D",40),new KeyValuePair<string,double>("pid_2_luid_0x0_0x1_phys_0_eng_0_engtype_3D",30),new KeyValuePair<string,double>("pid_3_luid_0x0_0x1_phys_0_eng_1_engtype_Copy",80)};Require(SystemUsage.BusiestGpu(values)==80&&SystemUsage.BusiestGpu(new KeyValuePair<string,double>[0])==null);});
   test("old-config-system-metrics-enabled-and-flags-roundtrip",()=>{var options=Json.Serializer.Deserialize<Settings>("{\"Interval\":5}");Require(options.ShowUpload&&options.ShowDownload&&options.ShowCpu&&options.ShowMemory&&options.ShowGpu&&options.ShowDisk);options.ShowGpu=false;options.ShowCredits=false;var restored=Json.Serializer.Deserialize<Settings>(Json.Encode(options));Require(!restored.ShowGpu&&!restored.ShowCredits&&restored.ShowMemory);});
   test("taskbar-legacy-and-full-width",()=>{var settings=new Settings {ShowUpload=false,ShowDownload=false,ShowCpu=false,ShowMemory=false,ShowGpu=false,ShowDisk=false};var data=TaskbarContent.Create(Data(Fixture),false);Require(TaskbarColumns.Width(TaskbarColumns.Create(data,null,TaskbarSelection.From(settings)))==366);settings.ShowUpload=settings.ShowDownload=settings.ShowCpu=settings.ShowMemory=settings.ShowGpu=settings.ShowDisk=true;Require(TaskbarColumns.Width(TaskbarColumns.Create(data,null,TaskbarSelection.From(settings)))==598);});
   test("taskbar-single-system-item-and-hidden-all",()=>{var choice=new TaskbarSelection {Cpu=true};var columns=TaskbarColumns.Create(TaskbarContent.Create(null,false),new SystemUsage {Cpu=8},choice);Require(columns.Count==1&&columns[0].Header=="CPU: 8 %"&&TaskbarColumns.Width(columns)==80);choice.Cpu=false;Require(TaskbarColumns.Width(TaskbarColumns.Create(TaskbarContent.Create(null,false),null,choice))==0);});
   test("taskbar-disable-a-token-keeps-other-value",()=>{var choice=new TaskbarSelection {Total=true};var data=TaskbarContent.Create(null,false);data.TotalTokens="累计 50亿";var columns=TaskbarColumns.Create(data,null,choice);Require(columns.Count==1&&columns[0].Header=="累计 50亿"&&columns[0].Value=="");});
   File.WriteAllText(path,Json.Encode(new {passed=results.Count-errors,failed=errors,tests=results}));return errors==0?0:1;
  }
  static void Require(bool condition){if(!condition)throw new Exception("assertion");}
 }
}
